steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{
      teams(name: \"Web\") {
        id
        name
        workflowStates(stateType: \"completed\") {
          id
          name
        }
      }
      users(firstName: \"Priya\") {
        id
        name
        firstName
      }
    }"
  }'
